import{_ as o,o as r,c as s,a2 as e}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"검색 기록","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/history.md","filePath":"ko-KR/user-guide/settings/history.md","lastUpdated":1789222057000}'),n={name:"ko-KR/user-guide/settings/history.md"};function i(a,t,l,g,d,c){return r(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="검색-기록" tabindex="-1">검색 기록 <a class="header-anchor" href="#검색-기록" aria-label="Permalink to &quot;검색 기록&quot;">​</a></h1><p>기록 설정 페이지에서는 Lertaro의 사용 흔적과 스마트 추천 가중치를 관리합니다. 상단에는 <strong>검색 기록</strong>과 <strong>키워드 기록</strong>의 2개 탭이 제공됩니다.</p><h2 id="_1-검색-기록-search-history" tabindex="-1">1. 검색 기록 (Search History) <a class="header-anchor" href="#_1-검색-기록-search-history" aria-label="Permalink to &quot;1. 검색 기록 (Search History)&quot;">​</a></h2><p>검색 결과에서 실제로 클릭하거나 Enter를 눌러 실행한 항목과 당시 사용했던 검색어를 쌍으로 학습하여 기억합니다.</p><ul><li><strong>스마트 우선 재호출</strong>: 이전 쿼리와 유사한 검색어를 입력하면 과거에 실행했던 항목이 결과 목록 상단에 우선적으로 추천됩니다(예: <code>bcomp</code>로 <code>BCompare.exe</code>를 실행한 적이 있다면 향후 <code>bc</code>만 입력해도 상위에 노출).</li><li><strong>사용량 기반 정렬</strong>: 기록 후보는 일치 시작 위치, 사용 횟수 내림차순, 최근 실행 시간 내림차순, 퍼지 일치 가중치 순으로 정렬됩니다. 이 규칙은 기록 후보에만 적용되며 다른 결과 유형의 정렬은 바뀌지 않습니다.</li><li><strong>인라인 윈도우 스마트 분류</strong>: 파일 대화상자의 인라인 검색 시 현재 열린 폴더 내부의 일치 항목은 &quot;현재 폴더&quot;, 나머지는 &quot;전체 검색&quot; 그룹으로 자동 분류됩니다.</li><li><strong>삭제된 경로 자동 필터링</strong>: 파일이 이동되거나 삭제된 경우 유효하지 않은 경로는 목록에서 자동 제외되며 동일 경로는 중복 표시되지 않습니다.</li><li><strong>관리 기능</strong>: <ul><li><strong>기록 기능 활성화</strong>: 전체 스위치. 끄면 기존 기록은 유지됩니다. 새 항목은 추가되지 않지만 기존 항목을 다시 실행하면 사용 횟수는 계속 누적됩니다.</li><li><strong>검색 필터링</strong>: 상단 검색창으로 특정 기록을 빠르게 검색.</li><li><strong>사용 횟수 및 정리</strong>: 각 항목에 실행 횟수가 표시됩니다. 횟수 임계값을 선택하고 <strong>N회 이하 기록 지우기</strong>를 누르면 사용 빈도가 낮은 항목을 삭제할 수 있으며, 개별 삭제와 <strong>모든 기록 삭제</strong>도 사용할 수 있습니다.</li><li><strong>실시간 업데이트</strong>: 다른 검색 창에서 새 항목을 실행하면 목록의 사용 횟수가 자동으로 갱신됩니다.</li></ul></li></ul><h2 id="_2-키워드-기록-keyword-history" tabindex="-1">2. 키워드 기록 (Keyword History) <a class="header-anchor" href="#_2-키워드-기록-keyword-history" aria-label="Permalink to &quot;2. 키워드 기록 (Keyword History)&quot;">​</a></h2><p>결과나 액션을 실행했거나 해당 검색어로 메인 윈도우를 열 때 실제로 사용한 <strong>원시 검색 문자열 자체</strong>를 기억합니다. 검색어만 입력한 뒤 퀵 검색창을 닫거나 포커스를 잃으면 기록에 추가되지 않습니다.</p><ul><li><strong>단축키 빠른 탐색</strong>: 퀵 검색창에서 <strong><code>Alt+Up</code></strong>(이전) / <strong><code>Alt+Down</code></strong>(다음)을 눌러 과거 검색어를 순서대로 불러올 수 있으며, **<code>Ctrl+Delete</code>**를 눌러 현재 표시된 검색어를 기록에서 즉시 삭제할 수 있습니다.</li><li><strong>사용 횟수 및 정리</strong>: 각 키워드에 사용 횟수가 표시됩니다. 횟수 임계값을 선택하고 <strong>N회 이하 기록 지우기</strong>를 누르면 사용 빈도가 낮은 키워드를 삭제할 수 있습니다.</li><li><strong>독립 관리</strong>: 검색 기록과 동일하게 <strong>기록 기능 활성화</strong> 스위치, 검색 필터링, 개별 삭제 및 <strong>모든 기록 삭제</strong> 버튼을 제공합니다. 끈 상태에서도 기존 키워드의 사용 횟수는 누적되지만 새 키워드는 추가되지 않습니다.</li></ul>',8)])])}const _=o(n,[["render",i]]);export{u as __pageData,_ as default};
